def solve(name,bg,mk):
    a=np.array(G[name+' input']); b=np.array(G[name+' output'])
    H,W=a.shape
    M={(int(r),int(c)) for r,c in zip(*np.where(a==mk))}
    # split marker cells into two groups by median row
    rs=sorted(r for r,c in M)
    med=(rs[len(rs)//2]+rs[len(rs)//2-1])/2
    Top={p for p in M if p[0]<med}; Bot={p for p in M if p[0]>=med}
    # align: shift Top so its bounding-box top-left lands at Bot's bbox top-left? Find shift maximizing overlap
    best=None
    def key(S,T):
        dr,Sr=min(p[0] for p in S)-min(q[0] for q in T); dc=Sr-min(q[1] for q in T)
        ov=len({(r+dr,c+dc) for r,c in S}&T)
        return ov
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            S={p+(dr,dc) for p in Top}
            ov=len(S&Bot)
            n=int(oov) if False else 0
            pass
    # simpler: brute force shifts mapping Top bbox origin -> some point; use bbox alignment
    tr=min(p[0] for p in Top); tc=min(p[1] for p in Top)
    br=min(p[0] for p in Bot); bc=min(p[1] for p in Bot)
    dr,dc=br-tr,bc-tc
    S={(r+dr,c+dc) for r,c in Top}
    newcells=S-Bot
    out=a.copy()
    for r,c in newcells:
        out[r,c]=1
    ok=np.array_equal(out,b)
    print(name,'match:',ok,'shift',(dr,dc),'newcells',len(newcells))
    return ok

