def comps_of(a,mk):
    lab,n=np.unique(a==mk,return_inverse=False)
    # flood fill of mk cells
    from collections import deque
    seen=set(); cs=[]
    for i in range(a.shape[0]):
        for j in range(a.shape[1]):
            if a[i,j]==mk and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); cells=[]
                while q:
                    r,c=q.popleft(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<a.shape[0] and 0<=cc<a.shape[1] and a[rr,cc]==mk and (rr,cc) not in seen:
                            seen.add((rr,cc)); q.append((rr,cc))
                cs.append(cells)
    return cs

