import numpy as np
from collections import Counter
def comps(a, val):
    lab=-np.ones((a.shape[0],a.shape[1]),int); n=0
    H,W=a.shape
    out=[]
    for r in range(H):
        for c in range(W):
            if a[r,c]==val and lab[r,c]<0:
                stack=[(r,c)]; lab[r,c]=n; comp=[]
                while stack:
                    x,y=stack.pop(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        xx,yy=x+dx,y+dy
                        if 0<=xx<H and 0<=yy<W and a[xx,yy]==val and lab[xx,yy]<0:
                            lab[xx,yy]=n; stack.append((xx,yy))
                out.append(comp)
                n+=1
    return out

def f(g):
    g=np.array(g); H,W=g.shape
    cnt=Counter(g.flat); bg=cnt.most_common(1)[0][0]
    mk=[c for c in cnt if c!=bg][0]
    out=g.copy()
    comps=comps(g,mk)
    # cluster by normalized shape (set of rel coords) allowing translation
    shapes={}
    for comp in comps:
        rs=[r-r0 for r,_ in comp]; cs=[c-c0 for _,c in comp]
        sh=(frozenset(zip(rs,cs)), len(comp))
