def solve_g(gi):
    g=np.array(gi); H,W=g.shape
    cnt=Counter(g.flat); bgc=int(cnt.most_common(1)[0][0])
    mk=[c for c in cnt if c!=bgc][0]
    cs=comps8(g,mk); cs.sort(key=len,reverse=True)
    T={(x,y) for x,y in cs[0]}; D={(x,y) for x,y in cs[1]}
    # pick shift so damaged aligns onto template: p = T cell => damaged position tr-dr, tc-dc; 
    # instead: for each template cell, compute where it maps relative to damaged copy, using majority vote
    best=None
    for dr in range(-H,H+1):
        for dc in range(-W,W+1):
            sh={(x+dr,y+dc) for x,y in D}
            inter=len(sh&T)
            key=(inter,-abs(dr)-abs(dc))
            if best is None or key>best[0]: best=(key,(dr,dc))
    _,shift=best; dr,dc=shift
    pred=g.copy()
    for (tr,tc) in sorted(T):
        p=(tr-dr,tc-dc)
        if 0<=p[0]<H and 0<=p[1]<W and g[p]==bgc and p not in D:
            pred[p[0],p[1]]=1
    return pred

